package ru.mcsa.bukkit;
import java.util.*;

// Ограниченный безопасный YAML: карты, списки и скаляры; без тегов, якорей и объектов.
public final class Yaml {
 private static final class Line {int indent;String text;Line(int indent,String text){this.indent=indent;this.text=text;}}
 private final List<Line> lines=new ArrayList<>();private int at;

 private static IllegalArgumentException bad(){return new IllegalArgumentException("Неподдерживаемый или повреждённый YAML");}
 public static Map<String,Object> parse(String text){
  if(text.length()>4*1024*1024)throw bad();Yaml parser=new Yaml();String pending=null;int indent=0;
  for(String raw:Strings.split(text,'\n')){
   if(raw.indexOf('\t')>=0)throw bad();String t=comment(raw).trim();if(t.isEmpty()||t.equals("---")||t.equals("..."))continue;
   if(pending==null){pending=t;indent=raw.indexOf(raw.trim());}else pending+=" "+t;
   if(flowDepth(pending)>0)continue;
   parser.lines.add(new Line(indent,pending));pending=null;
  }
  if(pending!=null)throw bad();if(parser.lines.isEmpty())return new LinkedHashMap<>();Object value;
  if(parser.lines.size()==1&&parser.lines.get(0).text.startsWith("{"))value=scalar(parser.lines.get(0).text,0);
  else{value=parser.block(parser.lines.get(0).indent,0);if(parser.at!=parser.lines.size())throw bad();}
  if(!(value instanceof Map))throw bad();return map(value);
 }
 private static int flowDepth(String text){int depth=0;char quote=0;for(int i=0;i<text.length();i++){char c=text.charAt(i);if(quote!=0){if(c=='\\'&&quote=='"')i++;else if(c==quote){if(c=='\''&&i+1<text.length()&&text.charAt(i+1)=='\'')i++;else quote=0;}}else if(c=='\''||c=='"')quote=c;else if(c=='['||c=='{')depth++;else if(c==']'||c=='}')depth--;if(depth<0)throw bad();}return depth;}
 @SuppressWarnings("unchecked") private static Map<String,Object> map(Object value){return (Map<String,Object>)value;}
 private static String comment(String s){char quote=0;for(int i=0;i<s.length();i++){char c=s.charAt(i);if(quote!=0){if(c=='\\'&&quote=='"'){i++;continue;}if(c==quote){if(quote=='\''&&i+1<s.length()&&s.charAt(i+1)=='\''){i++;continue;}quote=0;}}else if(c=='\''||c=='"')quote=c;else if(c=='#'&&(i==0||whitespace(s.charAt(i-1))))return s.substring(0,i);}if(quote!=0)throw bad();return s;}
 private static boolean whitespace(char c){return c==' '||c=='\t'||c=='\r'||c=='\n';}
 private static boolean dash(String s){return s.equals("-")||s.startsWith("- ");}
 private Object block(int indent,int depth){if(depth>64||at>=lines.size())throw bad();boolean sequence=dash(lines.get(at).text);List<Object> list=new ArrayList<>();Map<String,Object> map=new LinkedHashMap<>();while(at<lines.size()&&lines.get(at).indent==indent){String text=lines.get(at++).text;if(dash(text)!=sequence)throw bad();if(sequence){String tail=text.substring(1).trim();if(tail.isEmpty())list.add(at<lines.size()&&lines.get(at).indent>indent?block(lines.get(at).indent,depth+1):null);else if(colon(tail)>=0){Map<String,Object> item=new LinkedHashMap<>();entry(item,tail,indent+2,depth);if(at<lines.size()&&lines.get(at).indent>indent){Object rest=block(lines.get(at).indent,depth+1);if(!(rest instanceof Map))throw bad();for(Map.Entry<String,Object> e:map(rest).entrySet())put(item,e.getKey(),e.getValue());}list.add(item);}else{list.add(scalar(tail,depth+1));if(at<lines.size()&&lines.get(at).indent>indent)throw bad();}}else entry(map,text,indent,depth);}return sequence?list:map;}
 private void entry(Map<String,Object> map,String text,int indent,int depth){int c=colon(text);if(c<0)throw bad();Object key=scalar(text.substring(0,c).trim(),depth+1);if(!(key instanceof String))key=String.valueOf(key);String tail=text.substring(c+1).trim();Object value=tail.isEmpty()?(at<lines.size()&&lines.get(at).indent>indent?block(lines.get(at).indent,depth+1):null):scalar(tail,depth+1);put(map,(String)key,value);}
 private static void put(Map<String,Object> map,String key,Object value){if(map.containsKey(key))throw bad();map.put(key,value);}
 private static int colon(String text){char quote=0;int nesting=0;for(int i=0;i<text.length();i++){char c=text.charAt(i);if(quote!=0){if(c=='\\'&&quote=='"'){i++;continue;}if(c==quote)quote=0;}else if(c=='\''||c=='"')quote=c;else if(c=='['||c=='{')nesting++;else if(c==']'||c=='}')nesting--;else if(c==':'&&nesting==0&&(i+1==text.length()||whitespace(text.charAt(i+1))))return i;}return -1;}
 private static Object scalar(String text,int depth){if(depth>64)throw bad();String s=text.trim();if(s.isEmpty())return "";char first=s.charAt(0);if(first=='\''||first=='"'){if(s.length()<2||s.charAt(s.length()-1)!=first)throw bad();StringBuilder out=new StringBuilder();for(int i=1;i<s.length()-1;i++){char c=s.charAt(i);if(first=='\''&&c=='\''){if(i+1>=s.length()-1||s.charAt(++i)!='\'')throw bad();out.append('\'');}else if(first=='"'&&c=='\\'){if(++i>=s.length()-1)throw bad();char escaped=s.charAt(i);switch(escaped){case 'n':out.append('\n');break;case 'r':out.append('\r');break;case 't':out.append('\t');break;case '"':case '\\':case '/':out.append(escaped);break;case 'u':if(i+4>=s.length()-1)throw bad();out.append((char)Integer.parseInt(s.substring(i+1,i+5),16));i+=4;break;default:throw bad();}}else{if(c==first)throw bad();out.append(c);}}return out.toString();}
  if(first=='['||first=='{'){char end=first=='['?']':'}';if(s.charAt(s.length()-1)!=end)throw bad();List<String> parts=split(s.substring(1,s.length()-1));if(first=='['){List<Object> result=new ArrayList<>();for(String part:parts)result.add(scalar(part,depth+1));return result;}Map<String,Object> result=new LinkedHashMap<>();for(String part:parts){int c=flowColon(part);if(c<0)throw bad();put(result,String.valueOf(scalar(part.substring(0,c),depth+1)),scalar(part.substring(c+1),depth+1));}return result;}
  if("&*!|>%@`".indexOf(first)>=0)throw bad();if(s.equals("null")||s.equals("~"))return null;if(s.equalsIgnoreCase("true"))return true;if(s.equalsIgnoreCase("false"))return false;try{if(numeric(s)){if(s.indexOf('.')<0&&s.indexOf('e')<0&&s.indexOf('E')<0)return Long.parseLong(s);return Double.parseDouble(s);}}catch(NumberFormatException e){throw bad();}return s;
 }
 private static boolean numeric(String value){int at=0;if(value.charAt(0)=='+'||value.charAt(0)=='-')at++;boolean dot=false,exponent=false,digit=false;for(;at<value.length();at++){char c=value.charAt(at);if(c>='0'&&c<='9'){digit=true;continue;}if(c=='.'&&!dot&&!exponent){dot=true;continue;}if((c=='e'||c=='E')&&digit&&!exponent){exponent=true;digit=false;if(at+1<value.length()&&(value.charAt(at+1)=='+'||value.charAt(at+1)=='-'))at++;continue;}return false;}return digit;}
 private static int flowColon(String s){char quote=0;for(int i=0;i<s.length();i++){char c=s.charAt(i);if(quote!=0){if(c=='\\'&&quote=='"')i++;else if(c==quote)quote=0;}else if(c=='\''||c=='"')quote=c;else if(c==':')return i;}return -1;}
 private static List<String> split(String text){List<String> result=new ArrayList<>();if(text.trim().isEmpty())return result;int nesting=0,start=0;char quote=0;for(int i=0;i<text.length();i++){char c=text.charAt(i);if(quote!=0){if(c=='\\'&&quote=='"')i++;else if(c==quote){if(c=='\''&&i+1<text.length()&&text.charAt(i+1)=='\'')i++;else quote=0;}}else if(c=='\''||c=='"')quote=c;else if(c=='['||c=='{')nesting++;else if(c==']'||c=='}')nesting--;else if(c==','&&nesting==0){result.add(text.substring(start,i));start=i+1;}if(nesting<0)throw bad();}if(quote!=0||nesting!=0)throw bad();if(!text.substring(start).trim().isEmpty())result.add(text.substring(start));return result;}
 public static String write(Object value){return write(value,0);}
 private static String write(Object value,int depth){if(depth>64)throw bad();if(value==null)return "null";if(value instanceof Number||value instanceof Boolean)return value.toString();if(value instanceof Map){StringBuilder out=new StringBuilder("{");boolean first=true;for(Map.Entry<?,?> e:((Map<?,?>)value).entrySet()){if(!first)out.append(", ");first=false;out.append(write(String.valueOf(e.getKey()),depth+1)).append(": ").append(write(e.getValue(),depth+1));}return out.append('}').toString();}if(value instanceof Iterable){StringBuilder out=new StringBuilder("[");boolean first=true;for(Object item:(Iterable<?>)value){if(!first)out.append(", ");first=false;out.append(write(item,depth+1));}return out.append(']').toString();}StringBuilder out=new StringBuilder("\"");String s=value.toString();for(int i=0;i<s.length();i++){char c=s.charAt(i);if(c=='"'||c=='\\')out.append('\\').append(c);else if(c<32)out.append("\\u00").append("0123456789abcdef".charAt(c>>>4)).append("0123456789abcdef".charAt(c&15));else out.append(c);}return out.append('"').toString();}
}
